<?php
function search_movies($db) { $name=field($_GET,'name'); $genre=field($_GET,'genre'); $year=field($_GET,'year'); $price=field($_GET,'price'); if(strlen($name)>100||strlen($genre)>200||($year!==''&&!preg_match('/^\d{4}$/D',$year))||($price!==''&&!preg_match('/^\d{1,5}(\.\d{1,2})?$/D',$price))) throw new InvalidArgumentException('Invalid search filters.'); $pattern='%'.$name.'%'; $s=$db->prepare("SELECT * FROM movie WHERE movie_name LIKE ? AND (?='' OR genre=?) AND (?='' OR YEAR(date_released)=?) AND (?='' OR price<=?) ORDER BY date_released,movie_id"); $s->bind_param('sssssss',$pattern,$genre,$genre,$year,$year,$price,$price); $s->execute(); return $s->get_result()->fetch_all(MYSQLI_ASSOC); }
